def is_permutation(p, a3, a1):
    vals = set()
    for x in range(p):
        vals.add((a3 * x**3 + a1 * x) % p)
    return len(vals) == p

def count_pp(p):
    count = 0
    for a3 in range(p):
        for a1 in range(p):
            if is_permutation(p, a3, a1):
                count += 1
    return count

n11 = count_pp(11)
n61 = count_pp(61)
print(f"n11: {n11}, n61: {n61}")

def is_permutation(p, a3, a2, a1):
    vals = set()
    for x in range(p):
        vals.add((a3 * x**3 + a2 * x**2 + a1 * x) % p)
    return len(vals) == p

def count_pp_for_a2(p, a2):
    count = 0
    for a3 in range(p):
        for a1 in range(p):
            if is_permutation(p, a3, a2, a1):
                count += 1
    return count

n11_0 = count_pp_for_a2(11, 0)
n11_1 = count_pp_for_a2(11, 1)
print(f"n11(0): {n11_0}, n11(1): {n11_1}")
